using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Text.Json;

[McpServerToolType]
public class ApiTools(HttpClient httpClient, ILogger<ApiTools> logger)
{
    private static readonly JsonSerializerOptions s_jsonOptions = new() { WriteIndented = true };

    [McpServerTool, Description("Fetch a resource by its unique identifier from the REST API.")]
    public async Task<string> GetResource(
        [Description("The unique identifier of the resource to fetch")] string id,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching resource {Id}", id);
        var response = await httpClient.GetAsync($"/api/resources/{id}", cancellationToken);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }

    [McpServerTool, Description("List all resources, optionally filtered by category.")]
    public async Task<string> ListResources(
        [Description("Category name to filter by (optional)")] string? category = null,
        CancellationToken cancellationToken = default)
    {
        var url = category is not null
            ? $"/api/resources?category={Uri.EscapeDataString(category)}"
            : "/api/resources";

        logger.LogInformation("Listing resources with url {Url}", url);
        var response = await httpClient.GetAsync(url, cancellationToken);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }

    [McpServerTool, Description("Create a new resource with a name and optional description.")]
    public async Task<string> CreateResource(
        [Description("Name for the new resource")] string name,
        [Description("Optional description of the resource")] string? description = null,
        CancellationToken cancellationToken = default)
    {
        var payload = JsonSerializer.Serialize(new { name, description }, s_jsonOptions);
        var content = new StringContent(payload, System.Text.Encoding.UTF8, "application/json");

        logger.LogInformation("Creating resource {Name}", name);
        var response = await httpClient.PostAsync("/api/resources", content, cancellationToken);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }
}

